mapper.select:
WITH , trace AS ( SELECT 1 AS trace_level, k.output_lot_no AS parent_lot_no, k.input_lot_no AS lot_no, k.qty, k.result_id, k.linked_at, CAST(k.input_lot_no AS VARCHAR(1000)) AS sort_path FROM links k WHERE k.output_lot_no = #{lotNo}
UNION ALL
SELECT t.trace_level + 1, k.output_lot_no, k.input_lot_no, k.qty, k.result_id, k.linked_at, CAST(t.sort_path + '>' + k.input_lot_no AS VARCHAR(1000)) FROM trace t JOIN links k ON k.output_lot_no = t.lot_no )

WITH , trace AS ( SELECT 1 AS trace_level, k.input_lot_no AS parent_lot_no, k.output_lot_no AS lot_no, k.qty, k.result_id, k.linked_at, CAST(k.output_lot_no AS VARCHAR(1000)) AS sort_path FROM links k WHERE k.input_lot_no = #{lotNo}
UNION ALL
SELECT t.trace_level + 1, k.input_lot_no, k.output_lot_no, k.qty, k.result_id, k.linked_at, CAST(t.sort_path + '>' + k.output_lot_no AS VARCHAR(1000)) FROM trace t JOIN links k ON k.input_lot_no = t.lot_no )
